/* ── REQUEST TIMEOUT. PERF, 2026-08-07. ──
 *
 * Owner report, 2026-08-07: pages open with skeletons that never resolve. On a
 * bad connection a request's socket can stall mid-flight — the response never
 * arrives and it never errors. React Query then sits in `pending` forever and
 * the skeleton is permanent, with nothing on screen to say anything went wrong.
 *
 * This bounds every REST/auth/RPC request: if no response arrives in time, the
 * request is aborted, which surfaces as an error → React Query's `retry: 1` →
 * a visible error state the member can act on, instead of an eternal skeleton.
 *
 * ⚠️ UPLOADS ARE DELIBERATELY EXEMPT. A member posting a photo on a slow link
 * can legitimately take far longer than any read, and aborting that would turn
 * "slow post" into "failed post" — the exact regression build 1054 just fixed.
 * So storage object writes (POST/PUT/PATCH to /storage/v1/object/) carry no
 * timeout; only reads, which are small and fast, are bounded.
 *
 * A caller-supplied AbortSignal (React Query cancels queries on unmount /
 * key-change) is still honoured — whichever fires first wins.
 */
const READ_TIMEOUT_MS = 25_000;

function urlOf(input: RequestInfo | URL): string {
  if (typeof input === "string") return input;
  if (input instanceof URL) return input.href;
  return input.url;
}

function isUpload(input: RequestInfo | URL, init?: RequestInit): boolean {
  const method = (init?.method ?? "GET").toUpperCase();
  if (method === "GET" || method === "HEAD") return false;
  return /\/storage\/v1\/object\//.test(urlOf(input));
}

const timeoutFetch: typeof fetch = (rawInput, init) => {
  // N1: an edge function call runs next to the database (Seoul), not at the
  // nearest edge (Mumbai) — see src/lib/net/functionRegion.ts for the numbers.
  const input = pinFunctionRegion(rawInput);
  // Never bound an upload — a slow photo post must not become a failed post.
  if (isUpload(input, init)) return fetch(input, init);

  const controller = new AbortController();
  const abortForTimeout = () => {
    try {
      controller.abort(new DOMException("Request timed out", "TimeoutError"));
    } catch {
      controller.abort();
    }
  };
  const timer = setTimeout(abortForTimeout, READ_TIMEOUT_MS);

  // Honour React Query's own cancellation signal — first abort wins.
  const caller = init?.signal;
  if (caller) {
    if (caller.aborted) controller.abort((caller as AbortSignal).reason);
    else caller.addEventListener("abort", () => {
      try { controller.abort((caller as AbortSignal).reason); } catch { controller.abort(); }
    }, { once: true });
  }

  /**
   * REPORT THE OUTCOME, so a lost session can be explained afterwards.
   *
   * Owner, 2026-08-15: members are being signed out at random and nothing in
   * the app records WHY. This is the only place every REST and auth request
   * passes through, so it is the only place that can tell the difference
   * between a token refresh that the server REFUSED and one that WE cancelled
   * after 25 seconds — two completely different bugs that look identical once
   * the member is sitting on the logged-out screen.
   *
   * `sessionLossRecorder` deliberately imports nothing (a logger import here
   * would close a cycle through this very file), and every call below is
   * wrapped by the recorder itself, so this can never turn a slow request into
   * a failed one.
   */
  const url = urlOf(input);
  // OFF-3: every read also tells networkQuality how long it took, so the app
  // can say "slow connection" and load lighter images. It imports nothing.
  const started = Date.now();
  return fetch(input, { ...init, signal: controller.signal })
    .then((res) => {
      noteRequest(url, res.status);
      try { noteOutcome(Date.now() - started, false); } catch { /* never affects the request */ }
      return res;
    })
    .catch((err: unknown) => {
      // Our own abort and a dead network are different facts. `TimeoutError` is
      // the reason set by abortForTimeout above; anything else that throws here
      // never reached a server.
      const name = (err as { name?: string } | null)?.name;
      noteRequest(url, name === "TimeoutError" ? "timeout" : "network");
      // Only OUR timeout means "slow". A caller's cancellation says nothing about
      // the network, and an instant failure (refused, DNS, offline) is not
      // slowness — offline is reported by the browser itself.
      if (name === "TimeoutError") { try { noteOutcome(Date.now() - started, true); } catch { /* ignore */ } }
      throw err;
    })
    .finally(() => clearTimeout(timer));
};

/**
 * THE SIGN-IN LOCK, WITHOUT THE STALL. Owner 24 Nov 2026 (Admin → Users, screenshot): "Could not load members: Error:
 * Acquiring an exclusive Navigator LockManager lock "lock:sb-…-auth-token" timed out waiting 10000ms".
 *
 * supabase-js makes every tab of the site take turns on ONE browser lock around the saved session. When another tab
 * holds it and does not let go — typically a background tab Chrome has frozen in the middle of a token refresh — every
 * other tab waits 10 s and then FAILS the read it was doing. Now: wait at most 5 s for the other tab, then carry on
 * with this tab's own lock. The worst case is two tabs refreshing the same session at once, which the server accepts
 * (a refresh token may be reused for a few seconds). The background refresh's "is anyone refreshing? then skip"
 * (acquireTimeout 0) is kept exactly as before.
 */
const OTHER_TAB_WAIT_MS = 5_000;
async function authLock<R>(name: string, acquireTimeout: number, fn: () => Promise<R>): Promise<R> {
  const hasLocks = typeof globalThis.navigator !== 'undefined' && !!(globalThis.navigator as Navigator & { locks?: unknown }).locks;
  if (!hasLocks) return processLock(name, acquireTimeout, fn);
  if (acquireTimeout === 0) return navigatorLock(name, 0, fn);
  try {
    return await navigatorLock(name, acquireTimeout < 0 ? OTHER_TAB_WAIT_MS : Math.min(acquireTimeout, OTHER_TAB_WAIT_MS), fn);
  } catch (err) {
    if ((err as { isAcquireTimeout?: unknown } | null)?.isAcquireTimeout === true) return processLock(name, -1, fn);
    throw err;
  }
}

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
    lock: authLock,
  },
  global: {
    fetch: timeoutFetch,
  },
});
